    [Fact] public void StoppedIsDistinctFromSyncingAndReadyToSync(){var stopped=NewMappingWithDest("C:\\Work") with { Status=MappingStatus.Stopped };var syncing=NewMappingWithDest("C:\\Work") with { Status=MappingStatus.Syncing };var rts=NewMappingWithDest("C:\\Work") with { Status=MappingStatus.ReadyToSync };Assert.Equal(MappingStatus.Stopped,stopped.Status);Assert.NotEqual(MappingStatus.Syncing,stopped.Status);Assert.NotEqual(MappingStatus.ReadyToSync,stopped.Status);Assert.NotEqual(stopped.Status,syncing.Status);Assert.NotEqual(stopped.Status,rts.Status);}
    [Fact] public async Task ChooseDestinationSetsStoppedStatus(){var db=Path.Combine(Path.GetTempPath(),"oryno-dest-stopped-"+Guid.NewGuid()+".db");var store=new SqliteSyncMappingStore(db);await store.InitializeAsync();var m=NewMappingWithDest("C:\\Work") with { ServerRootId=Guid.NewGuid(), Status=MappingStatus.Stopped };await store.AddMappingAsync(m);var saved=await store.GetMappingAsync(m.MappingId);Assert.Equal(MappingStatus.Stopped,saved!.Status);}
