    [Fact] public async Task StartSyncTransitionsFromReadyToSync(){var db=Path.Combine(Path.GetTempPath(),"oryno-startsync-"+Guid.NewGuid()+".db");var store=new SqliteSyncMappingStore(db);await store.InitializeAsync();var mapping=NewMappingWithDest("C:\\Work") with { ServerRootId=Guid.NewGuid(), Status=MappingStatus.ReadyToSync };await store.AddMappingAsync(mapping);var rt=new SyncMappingRuntimeManager(store);await rt.StartSyncAsync(mapping);var saved=await store.GetMappingAsync(mapping.MappingId);Assert.True(saved!.Status==MappingStatus.Syncing||saved.Status==MappingStatus.Scanning);}
    [Fact] public async Task StartAfterStopRequeuesWaitingChanges(){var db=Path.Combine(Path.GetTempPath(),"oryno-start-stop-"+Guid.NewGuid()+".db");var root=Path.Combine(Path.GetTempPath(),"oryno-ss-root-"+Guid.NewGuid());Directory.CreateDirectory(root);await File.WriteAllTextAsync(Path.Combine(root,"new.txt"),"hi");var store=new SqliteSyncMappingStore(db);await store.InitializeAsync();var mapping=NewMapping(root) with { ServerRootId=Guid.NewGuid(), Status=MappingStatus.Stopped };await store.AddMappingAsync(mapping);var rt=new SyncMappingRuntimeManager(store);await rt.StartAsync(mapping);await Task.Delay(500);var pending=await store.GetPendingAsync(mapping.MappingId,DateTimeOffset.UtcNow);Assert.Contains(pending,o=>o.RelativePath=="new.txt");rt.Dispose();Directory.Delete(root,true);}
    [Fact] public async Task DestinationChangeInvalidatesPlanButPreservesFiles(){var db=Path.Combine(Path.GetTempPath(),"oryno-destchg-"+Guid.NewGuid()+".db");var store=new SqliteSyncMappingStore(db);await store.InitializeAsync();var m=NewMappingWithDest("C:\\Work") with { ServerRootId=Guid.NewGuid(), ServerRootName="Root" };await store.AddMappingAsync(m);await store.EnqueueAsync(new(Guid.NewGuid(),m.MappingId,OperationType.CreateFile,"a.txt",null,DateTimeOffset.UtcNow,0,DateTimeOffset.UtcNow,OperationState.Pending,null));var m2=m with { ServerDestinationRelativePath="Documents" };await store.UpdateMappingAsync(m2);var pending=await store.GetPendingAsync(m.MappingId,DateTimeOffset.UtcNow);Assert.NotNull(m2.ServerDestinationRelativePath);}
